interface RouteStrategy {
    Route buildRoute(Location from, Location to, RoutePrefs prefs);
}

final class DrivingStrategy implements RouteStrategy {
    public Route buildRoute(Location from, Location to, RoutePrefs prefs) {
        // Uses road graph + live traffic. Ignores transit timetables.
        return RoadGraph.fastest(from, to, prefs.avoidTolls());
    }
}

final class WalkingStrategy implements RouteStrategy {
    public Route buildRoute(Location from, Location to, RoutePrefs prefs) {
        // Uses pedestrian graph. Same signature, different cost model.
        return FootGraph.shortest(from, to);
    }
}

final class Navigator {
    private RouteStrategy strategy;

    Navigator(RouteStrategy strategy) { this.strategy = strategy; }

    void setStrategy(RouteStrategy strategy) { this.strategy = strategy; }

    Route navigate(Location from, Location to, RoutePrefs prefs) {
        // No branching on mode. Delegation only.
        return strategy.buildRoute(from, to, prefs);
    }
}

final class NavigatorFactory {
    private final Map<TravelMode, RouteStrategy> registry;

    NavigatorFactory(Map<TravelMode, RouteStrategy> registry) {
        this.registry = Map.copyOf(registry);
    }

    Navigator navigatorFor(TravelMode mode, RouteStrategy override) {
        if (override != null) return new Navigator(override);
        RouteStrategy s = registry.get(mode);
        if (s == null) throw new IllegalArgumentException("unknown mode: " + mode);
        return new Navigator(s);
    }
}
